const MAX_POST_LENGTH = 280;

const composeForm = document.querySelector('#compose-form');

if (composeForm) {
    const textarea = composeForm.elements.content;
    const counter = composeForm.querySelector('.char-counter');
    const submitButton = composeForm.querySelector('[type=submit]');

    const updateCounter = () => {
        const length = Array.from(textarea.value.trim()).length;
        const remaining = MAX_POST_LENGTH - length;

        counter.textContent = remaining;
        counter.classList.toggle('over-limit', remaining < 0);
        submitButton.disabled = length === 0 || remaining < 0;
    };

    textarea.addEventListener('input', updateCounter);

    // Ctrl + Enter (Cmd + Enter on Mac) publishes the post.
    textarea.addEventListener('keydown', (event) => {
        if (event.key === 'Enter' && (event.ctrlKey || event.metaKey) && !submitButton.disabled) {
            composeForm.requestSubmit();
        }
    });

    composeForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        submitButton.disabled = true;

        const data = await postJson('post.php', {action: 'create', content: textarea.value});

        if (data.code === 0) {
            window.location.href = 'home.php';
        } else {
            alertDialog(data.title, data.message);
            updateCounter();
        }
    });
}

document.querySelector('.timeline').addEventListener('click', async (event) => {
    const post = event.target.closest('.post');

    if (!post) {
        return;
    }

    const postId = post.dataset.postId;
    const likeButton = event.target.closest('.like-btn');

    if (likeButton) {
        likeButton.disabled = true;
        const data = await postJson('post.php', {action: 'like', post_id: postId});
        likeButton.disabled = false;

        if (data.code === 0) {
            likeButton.classList.toggle('liked', data.liked);
            likeButton.querySelector('.like-count').textContent = data.likes;
        } else {
            alertDialog(data.title, data.message);
        }
    }

    if (event.target.closest('.post-delete') && confirm('Delete this post?')) {
        const data = await postJson('post.php', {action: 'delete', post_id: postId});

        if (data.code === 0) {
            post.remove();
        } else {
            alertDialog(data.title, data.message);
        }
    }
});
